import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1787052895000}`),a={name:`reference/changelog.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="_0-1-3-2026-08-18" tabindex="-1">[0.1.3] - 2026-08-18 <a class="header-anchor" href="#_0-1-3-2026-08-18" aria-label="Permalink to “[0.1.3] - 2026-08-18”">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The API key is no longer left in the environment when <code>AUDIOBOOKSHELF_URL</code> is unset. <code>loadConfig</code> deleted it only at the very end, behind the early return for a missing URL, so in that state the key stayed in <code>process.env</code> for the whole process lifetime — readable in <code>/proc/&lt;pid&gt;/environ</code> and inherited by every child process. The deletion now happens before any branch.</li><li>A malformed <code>AUDIOBOOKSHELF_URL</code> is no longer echoed into the log. That branch fires precisely when the variable does not hold a URL, which most often means the API key was pasted into the wrong variable.</li><li><code>http://[::1]:…</code> no longer produces the &quot;plain http to a non-local host&quot; warning. <code>URL.hostname</code> keeps the brackets around an IPv6 literal, so the loopback check never matched that notation.</li></ul><h2 id="_0-1-2-2026-08-18" tabindex="-1">[0.1.2] - 2026-08-18 <a class="header-anchor" href="#_0-1-2-2026-08-18" aria-label="Permalink to “[0.1.2] - 2026-08-18”">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The architecture diagram no longer depends on the reader&#39;s operating system. It carried a <code>prefers-color-scheme</code> block, which resolves against the OS rather than the theme toggle of GitHub or npm — so dark-mode readers on a light OS got the light artwork on a dark page. The README now uses <code>&lt;picture&gt;</code>, which is resolved against the page, and the <code>&lt;img&gt;</code> that npm falls back to brings its own card instead of a media query.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The diagram is generated from a single source, <code>docs/assets/architecture.source.svg</code>, by <code>npm run assets</code>. The four rendered copies had already drifted apart; CI now fails if one of them is edited by hand.</li><li><code>docs/public/og.png</code> is generated at exactly 1280x640, GitHub&#39;s recommended size for a social preview, instead of being drawn by hand.</li></ul><h2 id="_0-1-1-2026-08-17" tabindex="-1">[0.1.1] - 2026-08-17 <a class="header-anchor" href="#_0-1-1-2026-08-17" aria-label="Permalink to “[0.1.1] - 2026-08-17”">​</a></h2><p>First release published by the automated pipeline, with npm provenance.</p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li>Multi-arch container image on GHCR (<code>ghcr.io/ni-c/audiobookshelf-mcp</code>) for linux/amd64 and linux/arm64, built with an SBOM and build provenance.</li><li>Documentation site at <a href="https://audiobookshelf-mcp.ni-c.de" target="_blank" rel="noreferrer">https://audiobookshelf-mcp.ni-c.de</a>, including a complete tool reference generated from the registered tools.</li><li>Listed in the official MCP registry as <code>io.github.ni-c/audiobookshelf-mcp</code>.</li><li><code>SECURITY.md</code> with the trust model, <code>CONTRIBUTING.md</code>, and issue forms.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The runtime image no longer contains npm. It was only ever there because the base image ships it, the entrypoint is plain <code>node</code>, and the dependency tree npm vendors accounted for every HIGH/CRITICAL advisory Trivy reported against the image — none of them in this project&#39;s own dependencies.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Test coverage raised from 93.9 % to 99.6 % of statements, mostly across the projections that absorb Audiobookshelf&#39;s varying response shapes, and the error paths.</li></ul><h2 id="_0-1-0-2026-08-17" tabindex="-1">[0.1.0] - 2026-08-17 <a class="header-anchor" href="#_0-1-0-2026-08-17" aria-label="Permalink to “[0.1.0] - 2026-08-17”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li>Initial release: MCP server for Audiobookshelf.</li><li>29 read tools: libraries, library items with filtering and paging, search, series, authors, personalized shelves, tags, genres, items, chapters, podcast episodes, the current user, listening progress, listening statistics, listening sessions, bookmarks, collections and playlists.</li><li>15 write tools: listening progress, bookmarks, collections and playlists.</li><li><code>AUDIOBOOKSHELF_READ_ONLY=true</code> registers the read tools only.</li><li>Confirmation tokens for the irreversible operations (<code>delete_collection</code>, <code>delete_playlist</code>, <code>delete_media_progress</code>).</li><li>Compact projections for every media response, with <code>detail: &quot;full&quot;</code> for the raw Audiobookshelf object.</li></ul>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};